@slots literal
{
  "scores": [
    16,
    9,
    56,
    39,
    37,
    9
  ],
  "minimum": 17
}

@qualifying jsEval
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
probe(typeof $slots === "object" && $slots !== null && !Array.isArray($slots), "the compiled slots wire must carry an object");
probe(Object.keys($slots).length > 0, "the compiled slots wire must not be empty");
const answer = await (async () => {
const slots = $slots;
probe(Array.isArray(slots.scores) && slots.scores.length > 0, "the scores must be a non-empty list");
probe(slots.scores.every((score) => Number.isInteger(score)), "every score must be a whole number");
probe(Number.isInteger(slots.minimum), "the qualifying minimum must be a whole number");
const qualifying = slots.scores.filter((score) => score >= slots.minimum);
probe(qualifying.every((score) => score >= slots.minimum), "only the scores at or above the minimum may qualify");
probe(qualifying.length >= 2, "at least two scores must qualify");
probe(qualifying.length < slots.scores.length, "at least one score must fail to qualify");
return qualifying;
})();
probe(answer !== undefined && answer !== null && String(answer).length > 0, "the computation returned an empty answer");
return answer;

